<?php
declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';$u=v700_require_user();$uid=(int)$u['id'];$tripId=(int)($_GET['trip']??$_POST['trip_id']??0);$trip=$tripId?v700_one('transport_trips_v700',$tripId,"status IN ('scheduled','boarding')"):null;$flash='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$id=v700_create_transport_booking($uid,$tripId,(int)($_POST['seats']??1),(string)($_POST['pickup_point']??''));$flash='Trip booked. Booking ID #'.$id;}}catch(Throwable $e){$err=$e->getMessage();}v700_public_header('Book Transport','Reserve seats on a scheduled trip.','transport');?>
<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker">TRIP BOOKING</span><h1><?=e($trip?'Book scheduled transport':'Trip unavailable')?></h1><p><?=$trip?e(date('d M Y, h:i A',strtotime($trip['departure_at']))).' · '.v700_money((float)$trip['fare']).' per seat':'Please return to transport search.'?></p></div></section><section class="v700-section soft"><div class="v700-shell" style="max-width:760px"><?php if($flash):?><div class="v700-alert success"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="v700-alert error"><?=e($err)?></div><?php endif;?><?php if($trip):?><form method="post" class="v700-panel v700-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="trip_id" value="<?=$tripId?>"><label>Seats<input type="number" name="seats" min="1" max="8" value="1"></label><label>Pickup Point<input name="pickup_point" placeholder="Optional boarding/pickup point"></label><button class="v700-btn primary">Confirm Booking</button></form><?php endif;?></div></section></main><?php v700_public_footer(); ?>
